/* ../packages/console-components/src/styles/conversation.css */
.cc-conversation-transcript {
  display: grid;
  align-content: start;
  gap: 18px;
  color-scheme: dark;
}
.cc-conversation-pane {
  position: relative;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  min-height: 0;
  container-type: inline-size;
  color-scheme: dark;
}
.cc-conversation-pane__scroll {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  scroll-padding-block: 26px 36px;
  scroll-snap-type: y proximity;
  scrollbar-gutter: stable;
  padding-left: 46px;
  padding-right: 18px;
}
.cc-conversation-pane__body {
  width: min(100%, var(--_cc-content-width));
  max-width: 100%;
  min-width: 0;
  margin: 0 auto;
}
.cc-conversation-turn {
  min-width: 0;
  display: grid;
  gap: 12px;
  scroll-margin-block: 26px;
  scroll-snap-align: start;
}
.cc-conversation-turn-rail {
  position: absolute;
  z-index: 8;
  top: calc(var(--cc-conversation-header-height, 0px) + 16px);
  bottom: calc(var(--cc-conversation-footer-height, 0px) + 64px);
  left: 10px;
  width: 18px;
  display: grid;
  align-content: center;
  pointer-events: none;
}
.cc-conversation-turn-rail__page {
  color: var(--_cc-text-secondary, #a3a3a3);
}
.cc-conversation-turn-rail__page:hover,
.cc-conversation-turn-rail__page:focus-visible {
  color: var(--_cc-text, #eee);
}
.cc-conversation-turn-rail__button:focus-visible {
  outline: 2px solid var(--_cc-accent, #8ba8ff);
  outline-offset: 1px;
  border-radius: 3px;
}
.cc-conversation-turn-rail__list {
  display: grid;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: min(560px, calc(100vh - var(--_cc-titlebar-height) - 120px));
  overflow: visible;
}
.cc-conversation-turn-rail__item {
  position: relative;
  z-index: 9;
  height: 7px;
  display: flex;
  align-items: center;
  pointer-events: auto;
}
.cc-conversation-turn-rail__button {
  position: relative;
  z-index: 10;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  cursor: pointer;
}
.cc-conversation-turn-rail__tick {
  width: 7px;
  height: 2px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.24);
  transition:
    width 140ms ease,
    background 140ms ease,
    opacity 140ms ease;
}
.cc-conversation-turn-rail__button:hover .cc-conversation-turn-rail__tick,
.cc-conversation-turn-rail__button:focus-visible .cc-conversation-turn-rail__tick {
  background: rgba(255, 255, 255, 0.52);
}
.cc-conversation-turn-rail__button.is-active .cc-conversation-turn-rail__tick,
.cc-conversation-turn-rail__button[aria-current=true] .cc-conversation-turn-rail__tick {
  background: rgba(255, 255, 255, 0.96);
}
.cc-conversation-turn-rail__item:has(+ .cc-conversation-turn-rail__item + .cc-conversation-turn-rail__item:hover) .cc-conversation-turn-rail__tick,
.cc-conversation-turn-rail__item:hover + .cc-conversation-turn-rail__item + .cc-conversation-turn-rail__item .cc-conversation-turn-rail__tick {
  width: 9px;
}
.cc-conversation-turn-rail__item:has(+ .cc-conversation-turn-rail__item:hover) .cc-conversation-turn-rail__tick,
.cc-conversation-turn-rail__item:hover + .cc-conversation-turn-rail__item .cc-conversation-turn-rail__tick {
  width: 11px;
}
.cc-conversation-turn-rail__item:hover .cc-conversation-turn-rail__tick {
  width: 13px;
}
.cc-conversation-turn-preview {
  position: absolute;
  left: 28px;
  top: 50%;
  width: min(320px, calc(100cqw - 72px));
  min-height: 0;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(33, 34, 36, 0.96);
  box-shadow: 0 18px 52px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  color: rgba(246, 247, 249, 0.96);
  display: grid;
  gap: 6px;
  opacity: 0;
  transform: translateY(-50%) translateX(-6px);
  pointer-events: none;
  transition: opacity 140ms ease, transform 140ms ease;
}
.cc-conversation-turn-rail__item:hover .cc-conversation-turn-preview,
.cc-conversation-turn-rail__button:focus-visible + .cc-conversation-turn-preview {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}
.cc-conversation-turn-preview__title {
  min-width: 0;
  color: rgba(248, 249, 251, 0.98);
  font-size: calc(14px * var(--_cc-window-scale));
  line-height: 1.25;
  font-weight: 600;
  overflow: hidden;
