/* ../packages/console-components/src/styles/pending-stack.css */
.cc-pending-stack {
  --bg: var(--_cc-surface-canvas);
  --bg-elev-1: var(--_cc-surface-card);
  --bg-elev-2: var(--_cc-surface-hover);
  --line: var(--_cc-border-soft);
  --ink: var(--_cc-foreground);
  --ink-muted: var(--_cc-foreground-muted);
  --ink-dim: var(--_cc-foreground-subtle);
  --accent: var(--_cc-member-accent);
  --accent-soft: var(--_cc-member-accent-soft);
  --danger: var(--_cc-negative);
  --ok: var(--_cc-positive);
  --mono: var(--_cc-font-mono);
  --motion-hover: var(--_cc-motion-duration) var(--_cc-motion-ease);
  flex: none;
  background: var(--bg-elev-1);
  border-top: 1px solid var(--line);
  position: relative;
}
.cc-pending-stack__head {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 2px 18px;
  height: 18px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
  background: var(--bg-elev-1);
}
.cc-pending-stack__head-count {
  color: var(--ink-muted);
  font-feature-settings: "tnum" 1;
  font-weight: 500;
}
.cc-pending-stack__head-hint {
  color: var(--ink-dim);
  text-transform: none;
  letter-spacing: 0;
}
.cc-pending-stack__head-spacer {
  flex: 1;
}
.cc-pending-stack__head-phase {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--ink-muted);
}
.cc-pending-stack__head-phase b {
  width: 4px;
  height: 4px;
  display: inline-block;
  background: var(--accent);
  animation: cc-pending-stack-pulse 1.6s infinite;
}
.cc-pending-stack__head-phase.is-idle b {
  background: var(--ok);
  animation: none;
}
.cc-pending-stack__head-phase.is-needs-retry {
  color: var(--danger);
}
.cc-pending-stack__head-phase.is-needs-retry b {
  background: var(--danger);
  animation: none;
}
.cc-pending-stack__head-btn {
  border: none;
  background: transparent;
  padding: 1px 3px;
  font: inherit;
  color: var(--ink-dim);
  letter-spacing: inherit;
  text-transform: uppercase;
  cursor: pointer;
}
.cc-pending-stack__head-btn:hover {
  color: var(--ink);
}
.cc-pending-stack__head-chev {
  font-family: var(--mono);
  font-size: 8px;
  display: inline-block;
  width: 8px;
  text-align: center;
}
@keyframes cc-pending-stack-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}
.cc-pending-stack__list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 120px;
  overflow-y: auto;
  border-top: 1px solid var(--line);
}
.cc-pending-stack.is-collapsed .cc-pending-stack__list {
  display: none;
}
.cc-pending-item {
  display: grid;
  grid-template-columns: 18px 1fr auto;
  align-items: center;
  column-gap: 6px;
  padding: 3px 18px 3px 10px;
  min-height: 24px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-elev-1);
  position: relative;
  transition: background var(--motion-hover);
}
.cc-pending-item:last-child {
  border-bottom: none;
}
.cc-pending-item:hover,
.cc-pending-item:focus-within {
  background: var(--bg-elev-2);
}
.cc-pending-item.is-head {
  background: var(--bg-elev-2);
}
.cc-pending-item.is-head::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--accent);
}
.cc-pending-item.is-needs-retry::before {
  background: var(--danger);
}
.cc-pending-item__lead {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.04em;
}
.cc-pending-item__grip {
  width: 8px;
  height: 12px;
  cursor: grab;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  align-content: center;
  opacity: 0;
  transition: opacity var(--motion-hover);
}
.cc-pending-item:hover .cc-pending-item__grip,
.cc-pending-item:focus-within .cc-pending-item__grip {
  opacity: 1;
}
.cc-pending-item__grip span {
  display: block;
  width: 2px;
  height: 2px;
  background: var(--ink-dim);
}
.cc-pending-item__grip:hover span {
  background: var(--ink);
}
.cc-pending-item.is-dragging {
  opacity: 0.4;
}
.cc-pending-item.drop-target.drop-above {
  box-shadow: 0 2px 0 0 var(--accent) inset;
}
.cc-pending-item.drop-target.drop-below {
  box-shadow: 0 -2px 0 0 var(--accent) inset;
}
.cc-pending-item__queue-glyph {
  font-family: var(--mono);
  color: var(--ink-dim);
  font-size: 10px;
  line-height: 1;
  display: inline-block;
}
.cc-pending-item.is-head .cc-pending-item__queue-glyph {
  color: var(--accent);
}
.cc-pending-item__body {
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 8px;
