}
.topo-dense:active .topo-dense__canvas {
  cursor: grabbing;
}
.topo-dense[data-drag-kind=node] .topo-dense__canvas,
.topo-dense[data-drag-kind=edge] .topo-dense__canvas {
  cursor: crosshair;
}
.topo-dense__labels {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.topo-dense__group-label {
  position: absolute;
  transform: translate(-50%, 0);
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  max-width: 160px;
  color: var(--ink);
  text-align: center;
  text-shadow: 0 1px 2px var(--bg);
  padding-top: 4px;
  border-top: 2px solid var(--line);
}
.topo-dense__group-label strong {
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--disp);
  font-size: 11.5px;
  font-weight: 600;
}
.topo-dense__group-label span {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-muted);
}
.topo-dense__node-label {
  position: absolute;
  transform: translate(-50%, -50%);
  max-width: 150px;
  padding: 4px 7px;
  border: 1px solid color-mix(in oklch, var(--line) 72%, transparent);
  border-top: 2px solid var(--line);
  border-radius: var(--r-sm);
  background: color-mix(in oklch, var(--bg-elev-1) 82%, transparent);
  color: var(--ink);
  text-align: center;
  text-shadow: 0 1px 2px var(--bg);
  font: 600 11px var(--disp);
  box-shadow: 0 6px 16px color-mix(in oklch, var(--bg) 36%, transparent);
  backdrop-filter: blur(6px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.topo-dense__inspector {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  max-width: calc(100% - 24px);
  padding: 7px 9px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: color-mix(in oklch, var(--bg-elev-1) 90%, transparent);
  backdrop-filter: blur(8px);
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--ink-muted);
}
.topo-dense__inspector strong {
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink);
  font-family: var(--disp);
  font-size: 12px;
}
.topo-dense__hover-label {
  position: absolute;
  z-index: 3;
  transform: translate(-50%, calc(-100% - 14px));
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  max-width: 220px;
  padding: 6px 9px;
  border: 1px solid color-mix(in oklch, var(--focus) 62%, var(--line));
  border-radius: var(--r-sm);
  background: color-mix(in oklch, var(--bg-elev-1) 92%, transparent);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--focus) 18%, transparent), 0 10px 28px color-mix(in oklch, var(--bg) 72%, transparent);
  backdrop-filter: blur(8px);
  pointer-events: none;
}
.topo-dense__hover-label::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 10px;
  height: 10px;
  transform: translateX(-50%) rotate(45deg);
  border-right: 1px solid color-mix(in oklch, var(--focus) 62%, var(--line));
  border-bottom: 1px solid color-mix(in oklch, var(--focus) 62%, var(--line));
  background: color-mix(in oklch, var(--bg-elev-1) 92%, transparent);
}
.topo-dense__hover-label strong {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink);
  font: 600 12px var(--disp);
}
.topo-dense__hover-label span {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink-muted);
  font: 10px var(--mono);
}
.topo-dense__edit-hint {
  position: absolute;
  z-index: 2;
  right: 12px;
  bottom: 12px;
  max-width: min(560px, calc(100% - 24px));
  padding: 6px 9px;
  border: 1px solid color-mix(in oklch, var(--line) 82%, transparent);
  border-radius: var(--r-sm);
  background: color-mix(in oklch, var(--bg-elev-1) 90%, transparent);
  box-shadow: 0 8px 24px color-mix(in oklch, var(--bg) 52%, transparent);
  backdrop-filter: blur(8px);
  color: var(--ink-dim);
  font: 10px/1.35 var(--mono);
  pointer-events: none;
}
.topo__board {
  position: relative;
  width: 100%;
  height: 100%;
}
.topo__viewbar--labels {
  margin-left: auto;
  margin-right: 8px;
  align-items: stretch;
}
.topo__viewbar--labels + .topo__viewbar {
  margin-left: 0;
}
.topo__viewbar-tag {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-faint);
  padding: 0 8px;
  display: inline-flex;
  align-items: center;
  border-right: 1px solid var(--line);
  background: var(--bg-elev-1);
}
.topo-edit {
  position: absolute;
  inset: 0;
  overflow: auto;
  scrollbar-gutter: stable;
  background:
    radial-gradient(
      circle at 50% -12%,
      color-mix(in oklch, var(--focus) 7%, transparent),
      transparent 36%),
    var(--bg);
}
.topo-edit__column {
  width: min(720px, calc(100% - 48px));
  min-width: 320px;
  margin: 0 auto;
  padding: 26px 0 48px;
}
.topo-edit__intro {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 0 2px 16px;
}
.topo-edit__intro strong {
  color: var(--ink);
  font: 600 15px/1.3 var(--disp);
  letter-spacing: -0.012em;
}
.topo-edit__intro span {
  color: var(--ink-muted);
  font: 12px/1.45 var(--disp);
}
.topo-edit__notice {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-bottom: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--bg-elev-1);
  color: var(--ink-muted);
  font: 11.5px/1.4 var(--disp);
}
.topo-edit__notice strong {
  color: var(--ink);
  font-weight: 600;
}
.topo-edit__notice.is-disabled {
  border-color: color-mix(in oklch, var(--ink-faint) 45%, var(--line));
}
.topo-edit__notice.is-degraded {
  border-color: color-mix(in oklch, var(--warn) 48%, var(--line));
}
.topo-edit__notice.is-conflict {
  border-color: color-mix(in oklch, var(--danger) 48%, var(--line));
}
.topo-edit__focus {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid color-mix(in oklch, var(--focus) 30%, var(--line));
  border-radius: 12px;
  background: color-mix(in oklch, var(--focus) 5%, var(--bg-elev-1));
  box-shadow: 0 10px 30px color-mix(in oklch, var(--bg) 30%, transparent);
}
.topo-edit__focus-identity,
.topo-edit__identity {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}
.topo-edit__focus-identity > span:last-child,
.topo-edit__identity-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}
.topo-edit__focus-identity strong,
.topo-edit__identity strong {
  overflow: hidden;
  color: var(--ink);
  font: 600 12.5px/1.25 var(--disp);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.topo-edit__focus-identity small,
.topo-edit__identity small {
  overflow: hidden;
  color: var(--ink-dim);
  font: 10.5px/1.35 var(--mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.topo-edit__dot {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border: 2px solid color-mix(in oklch, var(--topo-node-accent, var(--accent)) 25%, var(--bg-elev-1));
  border-radius: 50%;
  background: var(--topo-node-accent, var(--accent));
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--topo-node-accent, var(--accent)) 13%, transparent);
}
.topo-edit__dot.is-cross-scope {
  border-radius: 2px;
  transform: rotate(45deg);
}
.topo-edit__quiet-btn,
.topo-edit__bulk-actions button {
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--bg-elev-1);
  color: var(--ink-muted);
  font: 10.5px var(--mono);
  cursor: pointer;
}
.topo-edit__quiet-btn {
  align-self: start;
  padding: 5px 9px;
}
.topo-edit__bulk-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 7px;
  padding-top: 1px;
}
.topo-edit__bulk-actions button {
  padding: 5px 9px;
}
.topo-edit__bulk-actions button span {
  color: var(--ink-faint);
}
.topo-edit__quiet-btn:hover,
.topo-edit__bulk-actions button:not(:disabled):hover {
  border-color: color-mix(in oklch, var(--focus) 46%, var(--line));
  background: var(--bg-elev-2);
  color: var(--ink);
}
.topo-edit__bulk-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}
.topo-edit__search {
  position: sticky;
  top: 10px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  margin-bottom: 12px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in oklch, var(--bg-elev-1) 94%, transparent);
  box-shadow: 0 8px 22px color-mix(in oklch, var(--bg) 38%, transparent);
  backdrop-filter: blur(10px);
  color: var(--ink-faint);
}
.topo-edit__search:focus-within {
  border-color: color-mix(in oklch, var(--focus) 60%, var(--line));
  box-shadow: 0 0 0 2px color-mix(in oklch, var(--focus) 15%, transparent);
}
.topo-edit__search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font: 12px var(--disp);
}
.topo-edit__search input::placeholder {
  color: var(--ink-faint);
}
.topo-edit__search button {
  padding: 2px 4px;
  border: 0;
  background: transparent;
  color: var(--ink-faint);
  font: 16px var(--disp);
  cursor: pointer;
}
.topo-edit__roster {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--bg-elev-1);
  box-shadow: 0 16px 44px color-mix(in oklch, var(--bg) 28%, transparent);
}
.topo-edit__section + .topo-edit__section {
  border-top: 1px solid var(--line);
}
.topo-edit__section h3 {
  margin: 0;
  padding: 9px 14px 7px;
  border-bottom: 1px solid color-mix(in oklch, var(--line) 72%, transparent);
  background: color-mix(in oklch, var(--bg-elev-2) 55%, var(--bg-elev-1));
  color: var(--ink-faint);
  font: 600 9.5px/1.2 var(--mono);
  letter-spacing: 0.075em;
  text-transform: uppercase;
}
.topo-edit__row {
  position: relative;
  display: flex;
  min-height: 56px;
  align-items: center;
  gap: 12px;
  padding: 0 12px 0 14px;
  border-bottom: 1px solid color-mix(in oklch, var(--line) 62%, transparent);
  transition: background 120ms ease;
  content-visibility: auto;
  contain-intrinsic-size: auto 56px;
}
.topo-edit__section .topo-edit__row:last-child {
  border-bottom: 0;
}
.topo-edit__row:hover {
  background: var(--bg-elev-2);
}
.topo-edit__row.is-focus {
  background: color-mix(in oklch, var(--focus) 7%, var(--bg-elev-1));
}
.topo-edit__row.is-cross-scope::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 10px;
  bottom: 10px;
  border-left: 1px dashed var(--ink-faint);
  opacity: 0.65;
}
.topo-edit__identity {
  min-width: 0;
  flex: 1;
  align-self: stretch;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.topo-edit__identity:disabled {
  cursor: default;
}
.topo-edit__identity-copy .topo-edit__reason {
  overflow: visible;
  color: var(--ink-muted);
  font-family: var(--disp);
  white-space: normal;
}
.topo-edit__action {
  display: flex;
  min-width: 120px;
  align-items: flex-end;
  flex-direction: column;
  gap: 4px;
}
.topo-edit__status {
  color: var(--ink-faint);
  font: 9.5px/1.2 var(--mono);
}
.topo-edit__status.is-connected,
.topo-edit__status.is-succeeded {
  color: var(--ok);
}
.topo-edit__status.is-degraded,
.topo-edit__status.is-partial,
.topo-edit__status.is-pending_approval {
  color: var(--warn);
}
.topo-edit__status.is-conflict,
.topo-edit__status.is-denied,
.topo-edit__status.is-failed {
  color: var(--danger);
}
.topo-edit__toggle {
  min-width: 72px;
  height: 26px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg);
  color: var(--ink-muted);
  font: 10px var(--mono);
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background 120ms ease,
    color 120ms ease;
}
.topo-edit__toggle:hover {
  border-color: color-mix(in oklch, var(--focus) 55%, var(--line));
  color: var(--ink);
}
.topo-edit__toggle.is-connect,
.topo-edit__toggle.is-reconnect {
  border-color: color-mix(in oklch, var(--ok) 44%, var(--line));
  background: color-mix(in oklch, var(--ok) 9%, var(--bg));
  color: var(--ok);
}
.topo-edit__toggle.requires-approval {
  border-color: color-mix(in oklch, var(--warn) 44%, var(--line));
  background: color-mix(in oklch, var(--warn) 9%, var(--bg));
  color: var(--warn);
}
.topo-edit__toggle:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}
.topo-edit__empty {
  padding: 34px 18px;
  color: var(--ink-muted);
  font: 12px var(--disp);
  text-align: center;
}
.topo-edit__overflow {
  padding: 11px 14px;
  border-top: 1px solid var(--line);
  color: var(--ink-muted);
  font: 10.5px/1.35 var(--mono);
  text-align: center;
}
.topo-edit button:focus-visible,
.topo__reset:focus-visible,
.topo__viewbtn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
@media (max-width: 680px) {
  .topo-edit__column {
    width: calc(100% - 24px);
    min-width: 0;
    padding-top: 14px;
  }
  .topo__head {
    gap: 8px;
    padding-inline: 10px;
  }
  .topo__head-meta {
    display: none;
  }
  .topo__viewbtn {
    padding-inline: 8px;
  }
  .topo__viewbar--labels {
    display: none;
  }
}
.topo-roletree {
  padding: 14px 18px;
  font-size: 12.5px;
  color: var(--ink);
}
.topo-roletree__row {
  display: flex;
  flex-direction: column;
}
.topo-roletree__mob,
.topo-roletree__role {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px 5px 0;
  border-radius: var(--r-sm);
  background: transparent;
  border: none;
  cursor: pointer;
  font: inherit;
  color: inherit;
  text-align: left;
  transition: background 120ms ease;
}
.topo-roletree__mob:hover,
.topo-roletree__role:hover {
  background: var(--bg-elev-2);
}
.topo-roletree__mob.is-hot .topo-roletree__dot,
.topo-roletree__role.is-hot .topo-roletree__dot {
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--ok) 22%, transparent);
}
.topo-roletree__chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--ink-faint);
  transition: transform 150ms ease;
}
.topo-roletree__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}
.topo-roletree__label {
  font-weight: 500;
  color: var(--ink);
}
.topo-roletree__count {
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--ink-faint);
}
.topo-roletree__section {
  display: flex;
  flex-direction: column;
  padding-left: 18px;
}
.topo-roletree__pod {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px 0 8px 30px;
}
.topo-roletree__agent {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--bg);
  transition: background 120ms ease, border-color 120ms ease;
}
.topo-roletree__agent.is-hot {
  border-color: var(--ok);
  box-shadow: 0 0 0 2px color-mix(in oklch, var(--ok) 18%, transparent);
}
.topo-roletree__agent.is-busy {
  border-color: color-mix(in oklch, var(--accent) 50%, var(--line));
  background: color-mix(in oklch, var(--accent) 5%, var(--bg));
}
.topo-roletree__agent-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.topo-roletree__agent-label {
  font-size: 11.5px;
  color: var(--ink);
}
@keyframes topo-busy-rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.topo-roletree__busy {
  position: relative;
  width: 12px;
  height: 12px;
  margin-left: 4px;
  flex: none;
  border-radius: 50%;
  border: 1.5px solid color-mix(in oklch, var(--accent) 60%, transparent);
  border-top-color: var(--accent);
  border-right-color: var(--accent);
  animation: topo-busy-rotate 1.4s linear infinite;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.topo-roletree__busy-count {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--mono);
  font-size: 10px;
  color: var(--accent);
  letter-spacing: 0.02em;
}
.reduced-motion .topo-roletree__busy {
  animation: none;
  border-color: var(--accent);
  opacity: 0.7;
}
@media (prefers-reduced-motion: reduce) {
  .topo-roletree__busy {
    animation: none;
    border-color: var(--accent);
    opacity: 0.7;
  }
}
.cc-dock-panel__content .topo__head {
  padding: 12px 16px 10px;
}
.cc-dock-panel__content .topo__svg {
  inset: 42px 0 0 0;
}
.cc-dock-panel__content .topo__head p {
  display: none;
}
.cc-dock-panel__content .topo__legend {
  bottom: 10px;
  left: 12px;
  gap: 6px;
  font-size: 10px;
}

/* ../packages/console-components/src/conversation/approvals.css */
.cc-approval {
  --_approval-ink: var(--ink, var(--_cc-foreground, #e7e5e4));
  --_approval-muted: var(--ink-muted, var(--_cc-foreground-muted, #b0adaa));
  --_approval-line: var(--line, var(--_cc-border-soft, #494746));
  --_approval-positive: var(--cc-approval-positive, #28704c);
  --_approval-negative: var(--danger, var(--cc-approval-negative, #d37971));
  margin: 12px 0;
  padding: 18px;
  border: 1px solid var(--_approval-line);
  border-radius: 10px;
  background: var(--bg-elev-1, var(--_cc-surface-card, transparent));
  color: var(--_approval-ink);
}
.cc-approval__header {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  align-items: center;
  justify-content: space-between;
}
.cc-approval__header > strong {
  min-width: 0;
  font-size: 1.05em;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.cc-approval__status {
  display: inline-flex;
  padding: 4px 8px;
  border: 1px solid var(--_approval-line);
  border-radius: 999px;
  font-size: .75em;
  line-height: 1.3;
  color: var(--_approval-muted);
}
.cc-approval[data-state=pending] .cc-approval__status {
  color: var(--warn, #d2b579);
  background: color-mix(in srgb, var(--warn, #d2b579) 10%, transparent);
  border-color: color-mix(in srgb, var(--warn, #d2b579) 28%, transparent);
}
.cc-approval[data-state=failed] .cc-approval__status {
  color: var(--_approval-negative);
  border-color: color-mix(in srgb, var(--_approval-negative) 35%, transparent);
}
.cc-approval > p {
  margin-block: 12px;
  line-height: 1.55;
}
.cc-approval__scope {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 5px 12px;
  margin-block: 12px;
  font-size: .85em;
  line-height: 1.4;
}
.cc-approval__scope:empty {
  display: none;
}
.cc-approval__scope dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.cc-approval__scope dt {
  color: var(--_approval-muted);
}
.cc-approval__details {
  margin: 12px 0 0;
  font-size: .85em;
}
.cc-approval__details summary {
  width: fit-content;
  padding-block: 4px;
  color: var(--_approval-muted);
  cursor: pointer;
}
.cc-approval__details summary:hover {
  color: var(--_approval-ink);
}
.cc-approval__details summary:focus-visible {
  outline: 2px solid var(--accent, var(--_cc-link, #6ba1e6));
  outline-offset: 3px;
  border-radius: 3px;
}
.cc-approval__details pre {
  max-height: 320px;
  padding: 12px;
  border: 1px solid var(--_approval-line);
  border-radius: 6px;
  background: color-mix(in srgb, currentColor 3%, transparent);
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.cc-approval__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}
.cc-approval__actions button {
  min-height: 34px;
  padding: 7px 14px;
  border: 1px solid var(--_approval-line);
  border-radius: 6px;
  color: inherit;
  background: transparent;
  font: inherit;
  cursor: pointer;
}
.cc-approval__actions button:not(:disabled):hover {
  background: color-mix(in srgb, currentColor 7%, transparent);
}
.cc-approval__actions button[data-action=approve] {
  border-color: var(--_approval-positive);
  background: var(--_approval-positive);
  color: #fff;
  font-weight: 600;
}
.cc-approval__actions button[data-action=approve]:not(:disabled):hover {
  background: color-mix(in srgb, var(--_approval-positive) 86%, #000);
}
.cc-approval__actions button[data-action=reject] {
  color: var(--_approval-negative);
  border-color: color-mix(in srgb, var(--_approval-negative) 35%, transparent);
}
.cc-approval__actions button:disabled {
  opacity: .45;
  cursor: default;
}
.cc-approval__actions button:focus-visible {
  outline: 2px solid var(--accent, var(--_cc-link, #6ba1e6));
  outline-offset: 3px;
}
[data-approval-id][data-selected=true] > .cc-approval {
  outline: 2px solid var(--accent, var(--_cc-link, #6ba1e6));
  outline-offset: 2px;
}
.gating__list [data-approval-id] {
  margin-inline: 18px;
  outline: none;
}
.gating__list [data-approval-id]:focus-visible > .cc-approval {
  outline: 2px solid var(--accent, #6ba1e6);
  outline-offset: 2px;
}
.cc-approval-attention {
  padding: 7px 8px;
  border-bottom: 1px solid var(--line, var(--_cc-border-soft, #555));
}
.cc-approval-attention__open {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 34px;
  padding: 7px 9px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--ink-muted, var(--_cc-foreground-muted));
  font: inherit;
  font-size: 13px;
  line-height: 20px;
  text-align: left;
  cursor: pointer;
}
.cc-approval-attention__open:hover {
  background: var(--bg-hover, var(--_cc-surface-hover));
  color: var(--ink, var(--_cc-foreground));
}
.cc-approval-attention__open:focus-visible {
  outline: 2px solid var(--accent, var(--_cc-focus-ring));
  outline-offset: -2px;
}
.cc-approval-attention__icon {
  width: 17px;
  height: 17px;
  flex: none;
}
.cc-approval-attention__label {
  flex: 1;
  min-width: 0;
  font-weight: 550;
}
.cc-approval-attention__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 5px;
  background: color-mix(in srgb, currentColor 7%, transparent);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.cc-approval-attention__chevron {
  width: 12px;
  height: 12px;
  flex: none;
  opacity: .6;
}
.cc-approval-attention[data-pending=true] .cc-approval-attention__open {
  color: var(--ink, var(--_cc-foreground));
}
.cc-approval-attention[data-pending=true] .cc-approval-attention__icon,
.cc-approval-attention[data-pending=true] .cc-approval-attention__count {
  color: var(--accent, var(--_cc-member-accent));
}
.cc-approval-attention:is([data-state=stale], [data-state=unavailable]) .cc-approval-attention__count {
  color: var(--warn, var(--_cc-warning));
}
.cc-approval-attention__status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ../packages/console-components/src/styles/transport.css */
.cc-transport-status {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  min-width: 0;
  padding: 6px 12px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--ink-muted, var(--_cc-foreground-muted));
}
.cc-transport-status__dot {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: var(--warn, var(--_cc-warning));
}
.cc-transport-status[data-phase=live] .cc-transport-status__dot {
  background: var(--ok, var(--_cc-positive));
}
.cc-transport-status:is([data-phase=forbidden], [data-phase=consumer-failed], [data-phase=authentication-required]) .cc-transport-status__dot {
  background: var(--crit, var(--_cc-negative));
}
.cc-transport-status__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cc-transport-status button {
  flex: none;
  padding: 3px 7px;
  border: 1px solid var(--line, var(--_cc-border-soft));
  border-radius: 5px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.cc-transport-status button:hover {
  background: var(--bg-elev-1, var(--_cc-surface-hover));
  color: var(--ink, var(--_cc-foreground));
}
.cc-transport-status button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
.meta-topbar > .cc-transport-status {
  align-self: stretch;
  max-width: 42%;
}
@media (max-width: 700px) {
  .meta-topbar > .cc-transport-status {
    margin-left: auto;
    max-width: 48%;
    padding-inline: 6px;
  }
  .meta-topbar > .cc-transport-status[data-phase=live] .cc-transport-status__label {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
  }
}

