/* src/pending-stack.css */
.stack.stack--console {
  flex: none;
  background: var(--bg-elev-1);
  border-top: 1px solid var(--line);
  position: relative;
}
.stack--console .stack__head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 16px;
  min-height: 30px;
  height: auto;
  font-family: var(--sans);
  font-size: 12px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink-muted);
  background: var(--bg-elev-1);
}
.stack--console .stack__head-count {
  color: var(--ink-muted);
  font-feature-settings: "tnum" 1;
  font-weight: 500;
}
.stack--console .stack__head-hint {
  color: var(--ink-dim);
  text-transform: none;
  letter-spacing: 0;
}
.stack--console .stack__head-spacer {
  flex: 1;
}
.stack--console .stack__head-phase {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-muted);
}
.stack--console .stack__head-phase b {
  width: 5px;
  height: 5px;
  display: inline-block;
  background: var(--accent);
  animation: stack-pulse 1.6s infinite;
}
.stack--console .stack__head-phase.is-idle b {
  background: var(--ok);
  animation: none;
}
.stack--console .stack__head-btn {
  border: none;
  background: transparent;
  padding: 4px;
  min-height: 28px;
  font: inherit;
  color: var(--ink-dim);
  letter-spacing: inherit;
  text-transform: none;
  cursor: pointer;
}
.stack--console .stack__head-btn:hover {
  color: var(--ink);
}
.stack--console .stack__head-chev {
  font-family: var(--mono);
  font-size: 9px;
  display: inline-block;
  width: 10px;
  text-align: center;
}
@keyframes stack-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}
.stack--console .stack__list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: min(280px, 36vh);
  overflow-y: auto;
  border-top: 1px solid var(--line);
}
.stack.stack--console.is-collapsed .stack__list {
  display: none;
}
.stack--console .stk-item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  padding: 12px 16px 12px 14px;
  min-height: 48px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-elev-1);
  position: relative;
  transition: background var(--motion-hover);
}
.stack--console .stk-item:last-child {
  border-bottom: none;
}
.stack--console .stk-item:hover,
.stack--console .stk-item:focus-within {
  background: var(--bg-elev-2);
}
.stack--console .stk-item.is-head {
  background: var(--bg-elev-2);
}
.stack--console .stk-item.is-head::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--accent);
}
.stack--console .stk-item__lead {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-top: 3px;
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.04em;
}
.stack--console .stk-item__grip {
  width: 10px;
  height: 14px;
  cursor: grab;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  align-content: center;
  opacity: 0;
  transition: opacity var(--motion-hover);
}
.stack--console .stk-item:hover .stk-item__grip,
.stack--console .stk-item:focus-within .stk-item__grip {
  opacity: 1;
}
.stack--console .stk-item__grip span {
  display: block;
  width: 2px;
  height: 2px;
  background: var(--ink-dim);
}
.stack--console .stk-item__grip:hover span {
  background: var(--ink);
}
.stack--console .stk-item.is-dragging {
  opacity: 0.4;
}
.stack--console .stk-item.drop-target.drop-above {
  box-shadow: 0 2px 0 0 var(--accent) inset;
}
.stack--console .stk-item.drop-target.drop-below {
  box-shadow: 0 -2px 0 0 var(--accent) inset;
}
.stack--console .stk-item__queue-glyph {
  font-family: var(--mono);
  color: var(--ink-dim);
  font-size: 11px;
  line-height: 1;
  display: inline-block;
}
.stack--console .stk-item__queue-glyph svg,
.stack--console .stk-btn__glyph svg {
  display: block;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.stack--console .stk-item.is-head .stk-item__queue-glyph {
  color: var(--accent);
}
.stack--console .stk-item.is-frozen .stk-item__lead {
  justify-content: center;
}
.stack--console .stk-item__body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}
.stack--console .stk-item__text {
  color: var(--ink);
  font-size: 13px;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: none;
  min-width: 0;
}
.stack--console .stk-item__text--preview {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.stack--console .stk-item__text--expanded {
  white-space: pre-wrap;
  display: block;
  -webkit-line-clamp: unset;
  flex-basis: auto;
}
.stack--console .stk-item__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  font-family: var(--sans);
  font-size: 12px;
  line-height: 1.4;
  color: var(--ink-muted);
  letter-spacing: 0;
  flex: none;
  opacity: 1;
  transition: opacity var(--motion-hover);
}
.stack--console .stk-item:hover .stk-item__meta,
.stack--console .stk-item:focus-within .stk-item__meta {
  opacity: 1;
}
.stack--console .stk-item.is-head .stk-item__meta {
  opacity: 1;
}
.stack--console .stk-item__head-tag {
  color: var(--accent);
  font-weight: 500;
  text-transform: none;
  letter-spacing: 0;
}
.stack--console .stk-item__sending {
  color: var(--accent);
}
.stack--console .stk-item__state {
  font-weight: 600;
  color: var(--ink);
}
.stack--console .stk-item__age {
  margin-left: auto;
}
.stack--console .stk-item__explanation {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--ink-muted);
  overflow-wrap: anywhere;
}
.stack--console .stk-item__error {
  font-size: 12px;
  line-height: 1.5;
  color: var(--ink-muted);
  overflow-wrap: anywhere;
}
.stack--console .stk-item__error summary {
  cursor: pointer;
  width: fit-content;
  padding: 2px 0;
}
.stack--console .stk-item__error p {
  margin: 4px 0 0;
}
.stack--console .stk-item__error summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.stack--console .stk-item.is-editing {
  background: var(--bg-elev-2);
  padding-top: 10px;
  padding-bottom: 10px;
  align-items: flex-start;
}
.stack--console .stk-item.is-editing .stk-item__lead {
  padding-top: 4px;
}
.stack--console .stk-item__edit {
  display: flex;
  flex-direction: column;
  gap: 6px;
  grid-column: 2;
  min-width: 0;
}
.stack--console .stk-item__edit textarea {
  width: 100%;
  min-height: 30px;
  padding: 8px 10px;
  border: 1px solid var(--ink);
  background: var(--bg);
  color: var(--ink);
  font: inherit;
  resize: vertical;
  outline: none;
}
.stack--console .stk-item__edit-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-dim);
  letter-spacing: 0.04em;
}
.stack--console .stk-item__edit-spacer {
  flex: 1;
}
.stack--console .stk-kbd {
  border: 1px solid var(--line);
  padding: 1px 5px;
  background: var(--bg);
  font-family: var(--mono);
  color: var(--ink-muted);
}
.stack--console .stk-item__actions {
  display: flex;
  grid-column: 2;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  opacity: 1;
  transition: opacity var(--motion-hover);
}
.stack--console .stk-item:hover .stk-item__actions,
.stack--console .stk-item:focus-within .stk-item__actions {
  opacity: 1;
}
.stack--console .stk-item.is-head .stk-item__actions {
  opacity: 1;
}
.stack--console .stk-item.is-promoting .stk-item__actions {
  opacity: 0.5;
  pointer-events: none;
}
.stack--console .stk-item.is-editing .stk-item__actions {
  display: none;
}
.stack--console .stk-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px 9px;
  border: 1px solid transparent;
  background: transparent;
  border-radius: 6px;
  font-family: var(--sans);
  font-size: 12px;
  line-height: 18px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink-muted);
  min-height: 32px;
  height: auto;
  max-width: 100%;
  cursor: pointer;
}
.stack--console .stk-btn:hover {
  color: var(--ink);
  border-color: var(--line);
  background: var(--bg);
}
.stack--console .stk-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.stack--console .stk-btn__glyph {
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1;
}
.stack--console .stk-btn--icon {
  padding: 5px;
  min-width: 32px;
}
.stack--console .stk-btn--expand {
  padding-inline: 5px;
}
.stack--console .stk-btn--primary {
  color: var(--ink);
  background: var(--bg);
  border-color: var(--line-strong, var(--line));
  font-weight: 600;
}
.stack--console .stk-btn--primary:hover {
  color: var(--ink);
  background: var(--bg-elev-1);
  border-color: var(--ink-muted);
}
.stack--console .stk-btn--steer {
  color: var(--accent);
}
.stack--console .stk-btn--steer:hover {
  color: var(--bg);
  background: var(--accent);
  border-color: var(--accent);
}
.stack--console .stk-item.is-head .stk-btn--steer {
  border-color: var(--accent);
}
.stack--console .stk-btn--save {
  color: var(--accent);
  border-color: var(--accent);
}
.stack--console .stk-btn--save:hover {
  color: var(--bg);
  background: var(--accent);
  border-color: var(--accent);
}
.stack--console .stk-btn--trash:hover {
  color: var(--danger);
  border-color: var(--danger);
  background: var(--bg);
}
@keyframes stk-enter {
  from {
    opacity: 0;
    transform: translateY(-6px);
    max-height: 0;
    padding-top: 0;
    padding-bottom: 0;
  }
  to {
    opacity: 1;
    transform: translateY(0);
    max-height: 200px;
    padding-top: 10px;
    padding-bottom: 10px;
  }
}
.stack--console .stk-item.is-entering {
  animation: stk-enter 220ms ease;
}
@keyframes stk-drain {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  60% {
    opacity: 0;
    transform: translateY(-26px);
  }
  100% {
    opacity: 0;
    transform: translateY(-26px);
    max-height: 0;
    padding-top: 0;
    padding-bottom: 0;
    border-bottom-width: 0;
  }
}
.stack--console .stk-item.is-draining {
  animation: stk-drain 420ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
  pointer-events: none;
}
@keyframes stk-steer {
  0% {
    opacity: 1;
    transform: translateX(0);
  }
  35% {
    opacity: 1;
    transform: translateX(8px);
    background: var(--accent-soft);
  }
  100% {
    opacity: 0;
    transform: translate(0, -22px);
    max-height: 0;
    padding: 0;
    border: 0;
  }
}
.stack--console .stk-item.is-promoting {
  animation: stk-steer 360ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
  pointer-events: none;
}
@keyframes stk-trash {
  0% {
    opacity: 1;
  }
  35% {
    opacity: 0.3;
    background: color-mix(in oklch, var(--danger) 12%, transparent);
  }
  100% {
    opacity: 0;
    max-height: 0;
    padding: 0;
    border: 0;
  }
}
.stack--console .stk-item.is-trashing {
  animation: stk-trash 320ms ease forwards;
  pointer-events: none;
}
.stack--console.reduced-motion .stk-item.is-entering,
.stack--console.reduced-motion .stk-item.is-draining,
.stack--console.reduced-motion .stk-item.is-promoting,
.stack--console.reduced-motion .stk-item.is-trashing {
  animation: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .stack--console .stk-item.is-entering,
  .stack--console .stk-item.is-draining,
  .stack--console .stk-item.is-promoting,
  .stack--console .stk-item.is-trashing {
    animation: none !important;
  }
}

/* src/console-host.css */
*,
*::before,
*::after {
  box-sizing: border-box;
}
html,
body,
#root {
  margin: 0;
  padding: 0;
  height: 100%;
  width: 100%;
  overflow: hidden;
}
body {
  font-family:
    "Inter Tight",
    "Inter",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: oklch(0.16 0.005 80);
  color: rgba(232, 234, 237, 0.96);
  font-size: 13px;
  line-height: 1.45;
  letter-spacing: -0.003em;
}
button {
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  padding: 0;
}
button:disabled {
  cursor: default;
}
svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}
svg[data-svg=fit],
.topo__svg,
.rf__arrow {
  width: 100%;
  height: 100%;
  stroke-linecap: inherit;
  stroke-linejoin: inherit;
  stroke-width: inherit;
}
.rf__arrow {
  width: 40px;
  height: 12px;
  align-self: center;
}
.rf__arrow--drop {
  width: 12px;
  height: 24px;
}
.sprite-root {
  position: absolute;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden;
  pointer-events: none;
}
