  overflow: hidden;
  text-overflow: ellipsis;
}
.agent__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  padding-top: 3px;
}
.agent__badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  max-width: 100%;
  border: 1px solid var(--line);
  background: var(--bg-elev-1);
  color: var(--ink-dim);
  border-radius: 5px;
