  text-overflow: ellipsis;
}
.agent__badge[data-tone=warning] {
  border-color: color-mix(in oklch, var(--warn) 45%, var(--line));
}
.agent__badge[data-tone=critical] {
  border-color: color-mix(in oklch, var(--danger) 45%, var(--line));
}
.agent__badge[data-tone=success] {
  border-color: color-mix(in oklch, var(--ok) 45%, var(--line));
}
[data-cc-variant=terminal] .agent__badge {
  border-radius: 0;
}
.agent__meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  color: var(--ink-dim);
}
.agent__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.agent__pin {
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  background: transparent;
  color: var(--ink-faint);
  border-radius: var(--r-sm);
  cursor: pointer;
  opacity: 0;
  transition:
