    color 120ms ease,
    border-color 120ms ease,
    background 120ms ease;
}
.agent:hover .agent__pin,
.agent__pin:focus-visible {
  opacity: 1;
}
.agent__pin:hover,
.agent__pin[data-active=true] {
  color: var(--ink-muted);
  border-color: var(--line);
  background: var(--bg-elev-1);
}
.agent__pin[data-active=true] {
  color: var(--accent);
}
.agent__pin-icon {
  width: 14px;
  height: 14px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
}
.agent__pulse {
  display: flex;
  align-items: flex-end;
  gap: 1.5px;
  height: 12px;
}
.agent__pulse span {
  width: 2px;
  background: var(--ink-faint);
  border-radius: 1px;
  min-height: 1px;
}
[data-cc-variant=terminal] .agent__pulse span {
  border-radius: 0;
}
.agent[data-state=active] .agent__pulse span {
  background: var(--ink-dim);
}
.agent.is-active .agent__pulse span {
  background: var(--accent);
}
.agent__inbox {
  font-family: var(--mono);
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  font-weight: 600;
  line-height: 1.3;
}
[data-cc-variant=terminal] .agent__inbox {
  border-radius: 0;
}
.rail {
  background: var(--bg-sunken);
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  position: relative;
}
.rail--collapsed {
  padding: 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.rail__grip {
  width: 2px;
  height: 28px;
  background: var(--line-strong);
  border-radius: 1px;
  opacity: 0.7;
  display: block;
}
.rail__head {
  padding: 14px 16px 8px;
  display: flex;
  align-items: baseline;
  gap: 10px;
  border-bottom: 1px solid var(--line);
