  flex: none;
}
.rail__title {
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-dim);
  font-weight: 600;
  font-family: var(--disp);
}
.rail__sub {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
}
.rail__filters {
  display: flex;
  gap: 0;
  padding: 0;
  border-bottom: 1px solid var(--line);
  flex: none;
}
.rail__filter {
  flex: 1;
  padding: 8px 10px;
  font-size: 11px;
  color: var(--ink-dim);
  border-right: 1px solid var(--line);
  border-left: none;
  border-top: none;
  border-bottom: none;
  font-family: var(--disp);
  background: transparent;
}
.rail__filter:last-child {
  border-right: none;
}
.rail__filter.is-active {
  color: var(--ink);
  background: var(--bg-elev-1);
  box-shadow: inset 0 -2px 0 var(--accent);
}
.rail__filter:hover:not(.is-active) {
  color: var(--ink);
}
.rail__filter-count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
  margin-left: 4px;
}
.rail__list {
  flex: 1;
  overflow-y: auto;
  padding: 2px 0;
  min-height: 0;
}
.rail__empty {
  padding: 20px 14px;
  color: var(--ink-dim);
  font-size: 12px;
  font-family: var(--mono);
}
.signal {
  display: grid;
