}
.signal:hover {
  background: var(--bg-elev-1);
}
.signal__bar {
  background: var(--ink-faint);
  border-radius: 1px;
}
.signal[data-sev=critical] .signal__bar {
  background: var(--crit);
}
.signal[data-sev=warning] .signal__bar {
  background: var(--warn);
}
.signal[data-sev=info] .signal__bar {
  background: var(--ink-dim);
  opacity: 0.6;
}
.signal__body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.signal__label {
  font-size: 12px;
  font-weight: 500;
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: -0.003em;
}
.signal__chevron {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
  width: 10px;
  flex: none;
}
.signal__count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-dim);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 1px 5px;
  margin-left: auto;
}
.signal[data-sev=critical] .signal__label::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--crit);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--crit) 18%, transparent);
}
[data-cc-variant=terminal] .signal[data-sev=critical] .signal__label::before {
  border-radius: 0;
}
.signal__detail {
  font-size: 11.5px;
  color: var(--ink-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.signal__agent {
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--ink-dim);
}
.signal__events {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 6px;
  padding-left: 12px;
  border-left: 1px solid var(--line);
}
.signal__event {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px 0;
  text-align: left;
  background: transparent;
  border: none;
  color: inherit;
  font-family: var(--disp);
}
.signal__event:hover .signal__event-label {
  color: var(--ink);
}
.signal__memory-pivot {
  align-self: flex-start;
  font: inherit;
  font-size: 10.5px;
  color: var(--accent);
  background: none;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 1px 6px;
  margin-top: 2px;
  cursor: pointer;
}
.signal__memory-pivot:hover {
  border-color: var(--accent);
}
.signal__event-label {
  color: var(--ink-muted);
  font-size: 11px;
  font-weight: 500;
}
.signal__event-detail {
  color: var(--ink-dim);
  font-size: 10.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.signal__meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
.signal__time {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
}
.conv {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  min-height: 0;
  position: relative;
  overflow: hidden;
  background: var(--bg-elev-1);
}
.conv__head-frame {
  container-type: inline-size;
  flex: none;
  position: relative;
  z-index: 30;
}
.conv__head {
  padding: 14px 24px 12px;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
  position: relative;
  z-index: 30;
}
.conv__notice {
  padding: 8px 24px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-sunken);
  font-size: 13px;
  flex: none;
}
.conv__avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  display: grid;
  place-items: center;
  font-family: var(--disp);
  font-size: 12px;
  font-weight: 600;
  flex: none;
}
[data-cc-variant=terminal] .conv__avatar {
  border-radius: 0;
  background: transparent;
  border: 1px solid var(--accent);
}
.conv__target {
  flex: 1;
  min-width: 0;
}
.conv__title {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conv__identity {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--ink-dim);
  margin-top: 1px;
}
.conv__target .conv__identity {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conv__actions {
  margin-left: auto;
  display: flex;
  gap: 6px;
  flex: none;
}
.conv__action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 28px;
  min-height: 28px;
  flex: none;
  padding: 4px 10px;
  font-size: 11.5px;
  color: var(--ink-muted);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  font-family: var(--disp);
  background: transparent;
}
.conv__action-icon {
  display: inline-flex;
}
.conv__action-icon svg {
  width: 14px;
  height: 14px;
}
.conv__action-label {
  white-space: nowrap;
}
.conv__action:hover:not(:disabled) {
  color: var(--ink);
  border-color: var(--line-strong);
}
.conv__action:disabled {
  opacity: 0.45;
  cursor: default;
}
.conv__body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 18px 24px 12px 46px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 0;
  position: relative;
  z-index: 0;
  scroll-padding-block: 26px 36px;
  scroll-snap-type: y proximity;
}
.conv-turn {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  scroll-margin-block: 26px;
  scroll-snap-align: start;
}
.conv-turn-rail {
  position: absolute;
  z-index: 100;
  top: 72px;
  bottom: 150px;
  left: 12px;
  width: 18px;
  overflow: visible;
  pointer-events: none;
  display: grid;
  align-content: center;
}
.conv-turn-rail[data-overflowing=false] {
  visibility: hidden;
}
.conv-turn-rail__list {
  display: grid;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: min(560px, calc(100vh - 180px));
  overflow: visible;
}
.conv-turn-rail__item {
  position: relative;
  z-index: 8;
  height: 7px;
  display: flex;
  align-items: center;
  pointer-events: auto;
}
.conv-turn-rail__button {
  position: relative;
  z-index: 9;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  cursor: pointer;
}
.conv-turn-rail__tick {
  width: 7px;
  height: 2px;
  border-radius: 999px;
  background: color-mix(in oklch, var(--ink) 24%, transparent);
  transition: width var(--motion-hover), background var(--motion-hover);
}
.conv-turn-rail__tick--overflow {
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: transparent;
  border: 1.5px solid color-mix(in oklch, var(--ink) 32%, transparent);
}
.conv-turn-rail__button:hover .conv-turn-rail__tick--overflow {
  border-color: color-mix(in oklch, var(--ink) 60%, transparent);
}
.conv-turn-rail__button:hover .conv-turn-rail__tick,
.conv-turn-rail__button:focus-visible .conv-turn-rail__tick {
  background: color-mix(in oklch, var(--ink) 52%, transparent);
}
.conv-turn-rail__button.is-active .conv-turn-rail__tick,
.conv-turn-rail__button[aria-current=true] .conv-turn-rail__tick {
  background: color-mix(in oklch, var(--ink) 65%, transparent);
}
.conv-turn-rail__item:has(+ .conv-turn-rail__item + .conv-turn-rail__item:hover) .conv-turn-rail__tick,
.conv-turn-rail__item:hover + .conv-turn-rail__item + .conv-turn-rail__item .conv-turn-rail__tick {
  width: 9px;
}
.conv-turn-rail__item:has(+ .conv-turn-rail__item:hover) .conv-turn-rail__tick,
.conv-turn-rail__item:hover + .conv-turn-rail__item .conv-turn-rail__tick {
  width: 11px;
}
.conv-turn-rail__item:hover .conv-turn-rail__tick {
  width: 13px;
}
.conv-turn-preview {
  position: absolute;
  left: 28px;
  top: 50%;
  width: min(320px, calc(var(--conv-pane-inline-size, 100vw) - 72px));
  min-height: 0;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(33, 34, 36, 0.96);
  box-shadow: 0 18px 52px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  color: rgba(246, 247, 249, 0.96);
  display: grid;
  gap: 6px;
  opacity: 0;
  transform: translateY(-50%) translateX(-6px);
  pointer-events: none;
  transition: opacity var(--motion-hover), transform var(--motion-hover);
}
:is([data-cc-theme=light], .cc-theme-scope[data-cc-theme=light]) .conv-turn-preview {
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 44px rgba(33, 34, 36, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.64);
}
:is([data-cc-theme=light], .cc-theme-scope[data-cc-theme=light]) .conv-turn-preview__title {
  color: rgba(24, 24, 27, 0.96);
}
:is([data-cc-theme=light], .cc-theme-scope[data-cc-theme=light]) .conv-turn-preview__body {
  color: rgba(82, 82, 91, 0.78);
}
.conv-turn-rail__item:hover .conv-turn-preview,
.conv-turn-rail__button:focus-visible + .conv-turn-preview {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}
.conv-turn-preview__title {
  min-width: 0;
  color: rgba(248, 249, 251, 0.98);
  font-size: 14px;
  line-height: 1.25;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conv-turn-preview__body {
  min-width: 0;
  color: rgba(190, 195, 204, 0.72);
  font-size: 12px;
  line-height: 1.46;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
@media (max-width: 760px) {
  .conv-turn-rail {
    left: 8px;
  }
  .conv-turn-rail__button {
    width: 18px;
    height: 18px;
  }
  .conv-turn-rail__button:hover .conv-turn-rail__tick,
  .conv-turn-rail__button:focus-visible .conv-turn-rail__tick,
  .conv-turn-rail__button.is-active .conv-turn-rail__tick,
  .conv-turn-rail__button[aria-current=true] .conv-turn-rail__tick {
    width: 7px;
  }
  .conv-turn-preview {
    display: none;
  }
}
.conv__history {
  align-self: center;
  padding: 4px 10px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--ink-muted);
  font-family: var(--disp);
  font-size: 11px;
  flex: none;
}
.conv__history:hover:not(:disabled) {
  color: var(--ink);
  border-color: var(--line-strong);
}
.conv__history:disabled {
  opacity: 0.55;
  cursor: default;
}
.msg {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
  min-width: 0;
  max-width: 100%;
}
.msg__head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 8px;
  min-height: 22px;
  font-family: var(--disp);
  font-size: 11.5px;
  color: var(--ink-dim);
}
.msg__source {
  color: var(--ink-muted);
  font-weight: 600;
  letter-spacing: 0.01em;
}
.msg--user .msg__source {
  color: var(--ink);
}
.msg__source-detail {
  color: var(--ink-dim);
  overflow-wrap: anywhere;
}
.msg__source-detail::before {
  content: "\b7";
  margin-right: 8px;
  color: var(--ink-faint);
}
.msg__time {
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--ink-faint);
  font-variant-numeric: tabular-nums;
}
.msg__badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 999px;
  font-family: var(--disp);
  font-size: 10.5px;
  line-height: 16px;
  cursor: help;
}
.msg__badge--untrusted {
