  height: 24px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: color-mix(in oklch, var(--bg-elev-1) 92%, transparent);
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
