}
.workgraph-graph__detail-id .cc-copy-btn {
  flex: none;
  padding: 4px;
}
.meta-action-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 14px;
  background: var(--bg-elev-1);
  color: var(--err, #d4564e);
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
.meta-action-error button {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  padding: 2px 6px;
}
.conv__history-status {
  flex: none;
  padding: 4px 16px;
  color: var(--ink-muted);
  font-size: 12px;
}
.conv__head--compact {
  padding-block: 6px;
  gap: 8px;
}
.conv__head--compact .conv__avatar {
  width: 22px;
  height: 22px;
  font-size: 10px;
}
.conv__head--compact .conv__title {
  font-size: 12px;
}
.conv__head--compact .conv__action {
  min-height: 28px;
}
.conv__action:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.conv__identity {
  color: var(--ink-muted);
}
@container (max-width: 440px) {
  .conv__head,
  .pane__body .conv__head {
    padding-inline: 10px;
    gap: 6px;
  }
  .conv__actions {
    gap: 4px;
  }
  .conv__action {
    width: 28px;
    padding: 4px;
    border-color: transparent;
  }
  .conv__action:hover:not(:disabled) {
    background: var(--bg-elev-2);
  }
  .conv__action-icon svg {
    width: 16px;
    height: 16px;
  }
  .conv__action-label {
    display: none;
  }
}
.conv > .queue-storage-note {
  font-size: 12px;
  color: var(--ink-muted);
  padding: 6px 16px;
}
.queue-import {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
  margin: 4px 16px 6px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--bg-sunken);
  color: var(--ink-muted);
  font-family: var(--sans);
  font-size: 12px;
  line-height: 1.4;
}
.queue-import__icon {
  display: inline-flex;
  flex: none;
}
.queue-import__icon svg {
  width: 16px;
  height: 16px;
}
.queue-import__text {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}
.queue-import__title {
  color: var(--ink);
  font-weight: 500;
}
.queue-import__action {
  flex: none;
  min-height: 28px;
  padding: 4px 10px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--bg-elev-1);
  color: var(--ink);
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}
.queue-import__action:hover {
  background: var(--bg-elev-2);
  border-color: var(--line-strong);
}
.queue-import__action:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.gating__list > div > p {
  margin: 14px 18px;
  color: var(--ink-muted);
}
.runtime-scoped-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}
.runtime-panel-empty {
  gap: 12px;
}
.runtime-panel-empty h2,
.runtime-panel-empty p {
  margin: 0;
}
.runtime-panel-empty p {
  color: var(--ink-muted);
}
.runtime-scoped-panel > :last-child {
  flex: 1;
  min-height: 0;
}
.runtime-panel-selector {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 18px;
  border-bottom: 1px solid var(--line);
  font: 13px var(--font-sans);
}
.runtime-panel-selector select {
  flex: 1;
  min-width: 0;
  padding: 7px 10px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
}

/* src/panels/voice-bar.css */
.composer__voice {
  --voice-blue: #2868c9;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--voice-blue);
  color: #fff;
  transition: background 120ms ease, transform 120ms ease;
}
.composer__voice:hover:not(:disabled) {
  background: #2159ae;
}
.composer__voice:active:not(:disabled) {
  transform: scale(0.94);
}
.composer__voice[aria-pressed=true] {
  background: var(--ink);
  color: var(--bg);
}
.composer__voice:disabled {
  opacity: 0.45;
}
.composer__voice--checking {
  animation: composer-voice-checking 1.4s ease-in-out infinite;
}
@keyframes composer-voice-checking {
  0%, 100% {
    opacity: 0.55;
  }
  50% {
    opacity: 0.85;
  }
}
.composer__voice .voice-glyph svg {
  width: 22px;
  height: 22px;
  stroke-width: 2.3;
}
.voice-glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.voice-bar {
  --voice-input: #6da7ff;
  --voice-output: #61cbb3;
  container-type: inline-size;
  flex: none;
  padding: 12px 14px 8px;
  margin-bottom: 10px;
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  background: var(--bg-sunken);
  color: var(--ink);
  text-align: left;
}
[data-cc-theme=light] .voice-bar {
  --voice-input: #2868c9;
  --voice-output: #157661;
}
.voice-bar__header,
.voice-bar__heading,
.voice-bar__controls,
.voice-bar__channel-label {
  display: flex;
  align-items: center;
}
.voice-bar__header {
  justify-content: space-between;
  gap: 12px;
}
.voice-bar__heading {
  min-width: 0;
  gap: 10px;
}
.voice-bar__titles {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.voice-bar__name {
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.voice-bar__name strong {
  font-weight: 600;
}
.voice-bar__status {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 8px;
  font-size: 11px;
  color: var(--ink-muted);
}
.voice-bar__context {
  overflow-wrap: anywhere;
}
.voice-bar__indicator {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: none;
  background: var(--ink-dim);
}
.voice-bar[data-phase=active] .voice-bar__indicator {
  background: var(--voice-output);
}
.voice-bar[data-phase=error] .voice-bar__indicator {
  background: var(--danger);
}
.voice-bar__controls {
  gap: 4px;
  flex: none;
}
.voice-bar__control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--r-sm);
  color: var(--ink-muted);
}
.voice-bar__control:hover:not(:disabled) {
  background: var(--bg-elev-2);
  color: var(--ink);
}
.voice-bar__control[aria-pressed=true] {
  color: var(--ink);
  background: var(--bg-elev-2);
}
.voice-bar__control--close:hover:not(:disabled) {
  color: var(--danger);
}
.voice-bar__control:disabled {
  opacity: 0.4;
}
.voice-bar__separator {
  width: 1px;
  height: 16px;
  background: var(--line-strong);
  margin: 0 3px;
}
.voice-bar__control:focus-visible,
.composer__voice:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
}
.voice-bar__channels {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 20px;
  margin-top: 14px;
}
.voice-bar__channel {
  min-width: 0;
}
.voice-bar__channel-label {
  justify-content: space-between;
  gap: 6px;
  font-size: 10px;
  color: var(--ink-muted);
}
.voice-bar__channel-label span:first-child {
  font-weight: 600;
  color: var(--ink);
}
.voice-waveform {
  display: block;
  width: 100%;
  height: 44px;
}
.voice-waveform--microphone {
  color: var(--voice-input);
}
.voice-waveform--speaker {
  color: var(--voice-output);
}
.voice-bar__message {
  margin: 10px 0 4px;
  color: var(--ink-muted);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.voice-bar__message--error {
  color: var(--danger);
}
.main > .voice-bar {
  flex: none;
  margin: 0 16px 12px;
}
@container (max-width: 340px) {
  .voice-bar__header {
    align-items: flex-start;
    gap: 6px;
  }
  .voice-bar__heading {
    gap: 6px;
  }
  .voice-bar__indicator {
    margin-top: 6px;
  }
  .voice-bar__controls {
    gap: 0;
  }
  .voice-bar__separator {
    margin: 0 1px;
  }
  .voice-bar__channels {
    gap: 12px;
  }
  .voice-bar__channel-label {
    flex-wrap: wrap;
    gap: 2px 6px;
  }
}
@container (max-width: 260px) {
  .voice-bar__header {
    flex-wrap: wrap;
  }
  .voice-bar__heading {
    flex-basis: 100%;
  }
  .voice-bar__controls {
    margin-inline-start: auto;
  }
}
@media (pointer: coarse) {
  .voice-bar__control {
    width: 40px;
    height: 40px;
  }
  .composer__voice {
    width: 40px;
    height: 40px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .composer__voice {
    transition: none;
  }
  .composer__voice--checking {
    animation: none;
    opacity: 0.7;
  }
}
